/**
 * Documentation endpoints.
 *   GET  /openapi.json   — OpenAPI 3.1 spec (machine-readable)
 *   GET  /docs           — Interactive Swagger UI (developer-facing)
 *   GET  /docs/raw       — Raw HTML source (for debugging)
 *
 * The OpenAPI spec is auto-generated by Hono's `app.doc()` method from the
 * routes that use `createRoute()` with Zod schemas.
 *
 * Swagger UI is loaded from the official CDN (swagger-ui-dist@5 via unpkg).
 * No build step, no extra deps.
 */
import { Hono } from "hono";
import { OpenAPIHono } from "@hono/zod-openapi";
import type { Env, Variables } from "@/types/env";

const docs = new Hono<{ Bindings: Env; Variables: Variables }>();

/**
 * Mount this docs sub-app on the MAIN app (not on a sub-app), so it can
 * introspect every route that uses createRoute() — regardless of which
 * sub-app they live in.
 */
function registerDocs(app: OpenAPIHono<{ Bindings: Env; Variables: Variables }>) {
  // ============================================================================
  // GET /openapi.json — OpenAPI 3.1 spec
  // ============================================================================
  app.get("/openapi.json", (c) => {
    // Derive the current deployment URL from the request — this becomes
    // the default server for "Try it out" requests, so it always works
    // regardless of which Worker (prod / dev / local) served the spec.
    const currentOrigin = new URL(c.req.url).origin;
    const isDev = c.env.API_NAME.includes("-dev") || currentOrigin.includes("localhost");

    return c.json(
      app.getOpenAPI31Document({
        openapi: "3.1.0",
        info: {
          title: c.env.API_NAME,
          version: c.env.API_VERSION,
          description:
            "dateandtime.live API v2 — cities, time zones, holidays, on-this-day events. " +
            "Hono + Cloudflare D1 + Zod. See https://github.com/nsura2029-art/dateandtime-api-v2 for source.",
        },
        servers: [
          // Current deployment (always first → Swagger UI's default)
          { url: currentOrigin, description: `Current (${isDev ? "dev" : "prod"} — auto-detected)` },

          // Workers (Cloudflare-provided *.workers.dev subdomains)
          // Worker name comes from wrangler.toml [env.*] name field
          { url: "https://dt-api-v2.nsura2029.workers.dev", description: "Production Worker" },
          { url: "https://dt-api-v2-dev.nsura2029.workers.dev", description: "Dev Worker" },

          // Local dev
          { url: "http://localhost:8787", description: "Local (wrangler dev)" },
        ],
        tags: [
          { name: "Meta", description: "API metadata, health, status" },
          { name: "Cities", description: "GeoNames cities (33,945 rows)" },
          { name: "Countries", description: "ISO 3166-1 countries" },
          { name: "Time", description: "Current time, sunrise/sunset" },
          { name: "Timezones", description: "IANA timezone database" },
          { name: "Holidays", description: "Public holidays (Nager.Date + curated)" },
          { name: "OnThisDay", description: "Historical events by date" },
          { name: "DST", description: "Daylight saving transitions" },
          { name: "Popular", description: "Curated popular cities" },
          { name: "Search", description: "Full-text search (FTS5)" },
          { name: "Feedback", description: "User feedback" },
          { name: "Admin", description: "Data quality + admin ops" },
        ],
      })
    );
  });

  // ============================================================================
  // GET /docs — Interactive Swagger UI
  // ============================================================================
  app.get("/docs", (c) => {
    const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${c.env.API_NAME} — API Documentation</title>
  <link rel="stylesheet" href="https://unpkg.com/swagger-ui-dist@5.17.14/swagger-ui.css">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
  <style>
    :root {
      --c-bg: #0b0d10;
      --c-surface: #15181d;
      --c-surface-2: #1d2128;
      --c-border: #2a2f3a;
      --c-text: #e6e8eb;
      --c-text-dim: #8b95a3;
      --c-primary: #a78bfa;
      --c-accent: #ff5a8a;
      --c-success: #34d399;
      --c-warn: #fbbf24;
      --c-error: #f87171;
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; background: var(--c-bg); color: var(--c-text); font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; min-height: 100vh; }
    .topbar { display: none; } /* Hide default Swagger topbar */
    .swagger-ui .info { margin: 32px 0; }
    .swagger-ui .info .title { font-size: 32px; font-weight: 700; color: var(--c-text); }
    .swagger-ui .info .description { color: var(--c-text-dim); font-size: 14px; margin-top: 8px; }
    .swagger-ui .scheme-container { background: var(--c-surface); padding: 12px 16px; border-radius: 8px; border: 1px solid var(--c-border); }
    .swagger-ui .opblock { background: var(--c-surface); border: 1px solid var(--c-border); border-radius: 10px; margin-bottom: 12px; box-shadow: none; }
    .swagger-ui .opblock .opblock-summary { background: var(--c-surface); border-radius: 10px; }
    .swagger-ui .opblock-tag { color: var(--c-text); font-size: 24px; border: none; margin: 24px 0 12px; }
    .swagger-ui .opblock-tag small { color: var(--c-text-dim); }
    .swagger-ui .opblock .opblock-summary-method { font-family: 'JetBrains Mono', monospace; font-weight: 600; border-radius: 6px; min-width: 80px; }
    .swagger-ui .opblock.get .opblock-summary-method { background: var(--c-primary); }
    .swagger-ui .opblock.post .opblock-summary-method { background: var(--c-success); }
    .swagger-ui .opblock.delete .opblock-summary-method { background: var(--c-error); }
    .swagger-ui .opblock.put .opblock-summary-method { background: var(--c-warn); }
    .swagger-ui .opblock .opblock-summary-path { font-family: 'JetBrains Mono', monospace; color: var(--c-text); font-size: 14px; }
    .swagger-ui .opblock .opblock-summary-path__noslash { color: var(--c-text); }
    .swagger-ui .opblock-description-wrapper p, .swagger-ui .opblock-external-docs-wrapper p, .swagger-ui .opblock-title_normal p { color: var(--c-text-dim); }
    .swagger-ui table thead tr th, .swagger-ui table tbody tr td { color: var(--c-text); border-color: var(--c-border); }
    .swagger-ui .parameter__name { color: var(--c-text); font-family: 'JetBrains Mono', monospace; }
    .swagger-ui .parameter__type { color: var(--c-text-dim); }
    .swagger-ui .response-col_status { color: var(--c-text); font-family: 'JetBrains Mono', monospace; }
    .swagger-ui .response-col_description { color: var(--c-text-dim); }
    .swagger-ui .btn { background: var(--c-surface-2); color: var(--c-text); border: 1px solid var(--c-border); border-radius: 6px; font-family: 'Inter', sans-serif; }
    .swagger-ui .btn:hover { background: var(--c-primary); color: var(--c-bg); border-color: var(--c-primary); }
    .swagger-ui .btn.execute { background: var(--c-accent); color: var(--c-bg); border-color: var(--c-accent); font-weight: 600; }
    .swagger-ui .highlight-code { background: var(--c-surface-2); border-radius: 6px; }
    .swagger-ui .microlight { color: var(--c-text); background: transparent; }
    .swagger-ui section.models { background: var(--c-surface); border-radius: 10px; border: 1px solid var(--c-border); }
    .swagger-ui section.models h4 { color: var(--c-text); }
    .swagger-ui .model-box { background: var(--c-surface-2); border-radius: 6px; }
    .swagger-ui .model { color: var(--c-text); font-family: 'JetBrains Mono', monospace; }
    .swagger-ui .model-title { color: var(--c-text); font-family: 'JetBrains Mono', monospace; }
    .swagger-ui .prop-type { color: var(--c-primary); }
    .swagger-ui .prop-format { color: var(--c-text-dim); }
    .swagger-ui .markdown p, .swagger-ui .markdown li, .swagger-ui .markdown table { color: var(--c-text); }
    .swagger-ui .markdown code { background: var(--c-surface-2); color: var(--c-accent); padding: 2px 6px; border-radius: 4px; }
    .swagger-ui .markdown a { color: var(--c-primary); }
    .swagger-ui .markdown h1, .swagger-ui .markdown h2, .swagger-ui .markdown h3 { color: var(--c-text); border-color: var(--c-border); }
    .swagger-ui input[type=text], .swagger-ui textarea { background: var(--c-surface-2); color: var(--c-text); border: 1px solid var(--c-border); border-radius: 6px; font-family: 'JetBrains Mono', monospace; }
    .swagger-ui select { background: var(--c-surface-2); color: var(--c-text); border: 1px solid var(--c-border); border-radius: 6px; }
    .swagger-ui .expand-operation { background: transparent; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .hero { padding: 56px 0 32px; border-bottom: 1px solid var(--c-border); margin-bottom: 32px; }
    .hero-inner { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .hero h1 { margin: 0 0 8px; font-size: 36px; font-weight: 700; background: linear-gradient(120deg, var(--c-primary), var(--c-accent)); -webkit-background-clip: text; background-clip: text; color: transparent; }
    .hero p { margin: 0; color: var(--c-text-dim); font-size: 16px; }
    .badges { margin-top: 16px; display: flex; gap: 8px; flex-wrap: wrap; }
    .badge { display: inline-block; padding: 4px 10px; background: var(--c-surface-2); border: 1px solid var(--c-border); border-radius: 999px; font-size: 12px; color: var(--c-text-dim); font-family: 'JetBrains Mono', monospace; }
    .badge.live { color: var(--c-success); border-color: var(--c-success); }
  </style>
</head>
<body>
  <div class="hero">
    <div class="hero-inner">
      <h1>${c.env.API_NAME}</h1>
      <p>dateandtime.live API v${c.env.API_VERSION} — interactive documentation</p>
      <div class="badges">
        <span class="badge live">● live</span>
        <span class="badge">openapi 3.1</span>
        <span class="badge">swagger-ui 5</span>
        <span class="badge">hono</span>
        <span class="badge">cloudflare workers</span>
      </div>
    </div>
  </div>
  <div class="container">
    <div id="swagger-ui"></div>
  </div>
  <script src="https://unpkg.com/swagger-ui-dist@5.17.14/swagger-ui-bundle.js" crossorigin></script>
  <script>
    window.onload = () => {
      window.ui = SwaggerUIBundle({
        url: "/openapi.json",
        dom_id: "#swagger-ui",
        deepLinking: true,
        presets: [
          SwaggerUIBundle.presets.apis
        ],
        layout: "BaseLayout",
        defaultModelsExpandDepth: -1,
        defaultModelExpandDepth: 3,
        docExpansion: "list",
        filter: true,
        showExtensions: true,
        showCommonExtensions: true,
        tryItOutEnabled: true
      });
    };
  </script>
</body>
</html>`;
    return c.html(html);
  });

  // ============================================================================
  // GET /docs/raw — raw HTML (for debugging)
  // ============================================================================
  app.get("/docs/raw", (c) => c.text("Docs are served at /docs. OpenAPI spec at /openapi.json."));
}

export { registerDocs, docs };
